yakit.AutoInitYakit()
log.setLevel("info")
domains = cli.String("domain")
domains = str.ParseStringToLines(domains)
yakit.Info("主域名提取任务已启动")
yakit.EnableTable("主域名提取结果", ["主域名"]) 
outputTable = func(Domain) {
    data = make(map[string]var)
    data["主域名"] = Domain
    yakit.TableData("主域名提取结果", data)
}
domain = make([]string)
for index, element = range domains {
    if str.IsHttpURL(element){
        element = str.ReplaceAll(element, "http://", "")
        element = str.ReplaceAll(element, "https://", "")
    }
    if str.Contains(element, "/"){
        element = str.Split(element, "/")[0]
    }
    domain = append(domain, element)
}
domain = str.RemoveRepeat(domain)
for index, element = range domain{
    println(element)
    outputTable(element)
}
yakit.Info("主域名提取任务已完成")
